query:
For
\[
I_1(z)=\int_0^1 \frac{dx}{\sqrt{x(1-x)}\sqrt{1-zx}},
\]
show that it satisfies the second-order differential equation
\begin{equation}
\Big[\theta^2 - z\big(\theta+\tfrac12\big)^2\Big]\,I_1(z)=0,
\label{eq:ODE_N1_theta}
\end{equation}
and expand it into the standard form
\begin{equation}
z(1-z)I_1''(z)+(1-2z)I_1'(z)-\frac14 I_1(z)=0.
\label{eq:ODE_N1_std}
\end{equation}

For
\[
I_2(z)=\int_0^1\!\!\int_0^1 \frac{dx\,dy}{\sqrt{x(1-x)}\sqrt{y(1-y)}\sqrt{1-zxy}},
\]
show that it satisfies the third-order equation
\begin{equation}
\Big[\theta^3 - z\big(\theta+\tfrac12\big)^3\Big]\,I_2(z)=0.
\label{eq:ODE_N2_theta}
\end{equation}
